mod keep_local;
mod llama_probe;
mod meeting;
mod meeting_events;
mod model_jobs;
mod models;
mod obsidian;
mod offload;
#[cfg(test)]
mod page_names_tests;
mod plain_text;
#[cfg(windows)]
mod power_win;
