use std::sync::Arc;
use std::time::Instant;

use tauri::Manager;
use tauri_specta::Event;

/// A sink that sends each event to this app's own webview (nothing leaves the device).
fn emitter<E>(app: &tauri::AppHandle) -> Arc<dyn Fn(E) + Send + Sync>
where
    E: Event + serde::Serialize + Clone + 'static,
{
    let handle = app.clone();
    Arc::new(move |e: E| {
        let _ = e.emit(&handle);
    })
}

fn main() {
    // The hidden model check mode runs and exits before anything of the app (Tauri, the
    // store, the window) is built.
    let args: Vec<std::ffi::OsString> = std::env::args_os().skip(1).collect();
    // Crash logs (T9.1e) go to the app's data folder, also from the check; the replay mode keeps
    // them in its own `--data` once that is checked.
    if !headless::asked(&args) {
        crash::install_default();
        // Before any model or child process, and in the child modes too (T9.1t). The replay mode
        // leaves the user's registry alone.
        #[cfg(windows)]
        wer_win::opt_out();
    }
    // The hidden child modes (model check, llama.cpp and CUDA trials, GPU summary, NPU compile).
    if let Some(code) = child_modes::run(&args) {
        std::process::exit(code);
    }
    earshot_runtime::summary_child::use_this_exe();
    earshot_runtime::npu_compiled::use_this_exe();
    // So does the replay mode of `accept m7`: no window or webview exists in it.
    if let Some(code) = headless::main_if_asked(&args) {
        std::process::exit(code);
    }
    // Only the app itself: a child may be running while an earlier crash's dump is being written.
    crash::remove_old_dumps();
    let by_windows = shell::started_by_windows(&args);
    let builder = ipc::specta_builder();
    let gate = activity::WorkGate::for_app();
    tauri::Builder::default()
        // First, as its docs ask: a second start of Earshot opens this one's window instead of
        // a second recorder and tray icon.
        .plugin(tauri_plugin_single_instance::init(|app, _, _| {
            if let Some(shell) = app.try_state::<Arc<shell::Shell>>() {
                shell.show_window();
            }
        }))
        .plugin(tauri_plugin_global_shortcut::Builder::new().build())
        .invoke_handler(builder.invoke_handler())
        .on_window_event(|window, event| {
            if let Some(shell) = window.try_state::<Arc<shell::Shell>>() {
                shell.on_window_event(window, event);
            }
        })
        .setup(move |app| {
            builder.mount_events(app);
            // Opening the store runs migrations once; a failure is kept and reported by the
            // commands that need the store, so the window still opens.
            let state = ipc::AppState::open_default();
            // A crash while replacing the speech helpers: back before anything reads them.
            if let Ok(services) = state.services() {
                let models = earshot_runtime::host::model_dir(&services.data);
                earshot_runtime::host::recover_extractions(&models);
                // The first start of a version that marks unread summaries (T12.76) marks every
                // summary already there as read, once and in one transaction, before the window
                // can list the meetings, so an upgrade lights no mark. A failure only means some
                // marks show.
                let _ = earshot_runtime::summary_seen::mark_existing_once(&services);
            }
            // The CUDA switch (T8.4af) before anything can call llama.cpp or load ONNX Runtime,
            // whose libraries cannot be replaced once loaded. It closes their gates and returns at
            // once; its work runs on a thread, so the window and the tray do not wait. Off, it costs
            // one store read.
            let cuda_files: Arc<dyn earshot_runtime::cuda_switch::CudaFiles> =
                cuda_files::ManifestCudaFiles::new(Arc::new(earshot_runtime::SystemClock));
            let handle = app.handle().clone();
            let cuda_start = state.services().map_or_else(
                |_| cuda_settings::CudaLatch::resolved_off(),
                |services| {
                    cuda_settings::begin(&services, Arc::clone(&cuda_files), move || {
                        let _ = cuda_settings::CudaEvent::StartChecked.emit(&handle);
                    })
                },
            );
            let cuda_latch = Arc::clone(&cuda_start);
            app.manage(cuda_start);
            // The NPU model a meeting would load, compiled in the helper now (T12.12b), so the
            // first meeting usually loads it in a second. Nothing loads in this process.
            #[cfg(target_arch = "aarch64")]
            if let Ok(services) = state.services() {
                let models = earshot_runtime::host::model_dir(&services.data);
                let _ = std::thread::Builder::new()
                    .name("earshot-npu-prepare".into())
                    .spawn(move || {
                        let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                            earshot_runtime::host::prepare_npu_model(&services, &models)
                        }));
                    });
            }
            // Recordings this app was closed during get their audio back (T9.18), then audio
            // retention runs and periodically after (T7.4k): retention's sweep must never see
            // unfinished audio before recovery has adopted it.
            let retention = storage_settings::RetentionStatus::default();
            // Damaged items (T14.65): every scan of the store runs through one gate; the
            // start-up scan runs once recovery has finished, off the main thread.
            let damage_scans = state.services().ok().map(|services| {
                let handle = app.handle().clone();
                let scans = damage::Scans::for_app(
                    services,
                    Arc::new(move |e: damage::DamageEvent| {
                        // Only to this app's own webview; counts and flags only.
                        let _ = e.emit(&handle);
                    }),
                );
                damage::set_app_scans(&scans);
                scans
            });
            if let Ok(services) = state.services() {
                let handle = app.handle().clone();
                let scans = damage_scans.clone();
                recovery::spawn(
                    services,
                    retention.clone(),
                    storage_settings::RETENTION_PERIOD,
                    move |_| {
                        let _ = shell::ShellEvent::RecordingsRecovered.emit(&handle);
                    },
                    move || {
                        if let Some(scans) = scans {
                            scans.scan_soon();
                        }
                    },
                );
            }
            // Replaced transcript text from before T14.47 is cleared once per store, on its own
            // thread (docs/sync-spec.md 15.6); it gives way to sync and to recordings itself. A
            // failure is the next start's to retry.
            if let Ok(services) = state.services() {
                let _ = earshot_runtime::replaced_text::spawn(
                    &services,
                    Arc::new(std::sync::atomic::AtomicBool::new(false)),
                );
            }
            // In-app updates (T9.1b): what an earlier update left goes first; a check only if the
            // user turned automatic checks on, at the start and then on their schedule (T12.22).
            let update_sink: update_settings::UpdateSink = emitter(app.handle());
            let update_dir = state.data_dir().map(earshot_runtime::update::updates_dir);
            if let Some(dir) = &update_dir {
                earshot_runtime::update::remove_leftovers(dir);
            }
            let update_clock: earshot_runtime::SharedClock = Arc::new(earshot_runtime::SystemClock);
            let handle = app.handle().clone();
            let record_services = state.services().ok();
            let record_clock = Arc::clone(&update_clock);
            let update_recorder: update_settings::CheckRecorder =
                Arc::new(move |end: &update_settings::CheckEnd| {
                    if let Some(services) = &record_services {
                        let _ = update_settings::after_check(
                            services,
                            end,
                            earshot_core::identity::Clock::now_unix_ms(record_clock.as_ref()),
                            |version| {
                                handle
                                    .try_state::<Arc<shell::Shell>>()
                                    .is_some_and(|shell| shell.on_update_found(version))
                            },
                        );
                    }
                });
            let update_jobs = update_settings::UpdateJobs::with_recorder(
                Arc::new(update_settings::HostUpdates::new(
                    update_dir,
                    Arc::clone(&update_clock),
                )),
                update_sink,
                update_recorder,
            );
            let check_now = state.services().is_ok_and(|services| {
                earshot_runtime::update::auto_check(&services.store()).unwrap_or(false)
            });
            if check_now {
                let _ = update_jobs.start_check(true);
            }
            if let Ok(services) = state.services() {
                update_settings::spawn_schedule(services, update_jobs.clone(), update_clock);
            }
            // Sync (T11.3a): started off the setup path (Credential Manager is read first).
            let sync = std::sync::Arc::new(sync_settings::SyncHost::new(std::sync::Arc::new(
                sync_vault::SyncCredentials::app(),
            )));
            // Gone on sleep, online on resume (T11.3ca).
            #[cfg(windows)]
            let _ = power_win::watch(std::sync::Arc::clone(&sync));
            // Summary offload (T11.3db, T12.63b): a computer step of the order of summary
            // writers asks that computer when it is tried.
            let computers = summary_order::ComputerSlot::default();
            if let Ok(services) = state.services() {
                let vault = sync.vault();
                let _ = computers.set(Arc::new(move |device| {
                    earshot_runtime::offload::choose_device_now(
                        &services,
                        Arc::clone(&vault),
                        device,
                    )
                }));
            }
            let sync_for_start = Arc::clone(&sync);
            if let Some(scans) = &damage_scans {
                // What each tick says of damaged rows, and the end of a Repair (T14.65).
                let scans = Arc::clone(scans);
                let host = Arc::clone(&sync);
                sync.set_damage_listener(Arc::new(move |t: &earshot_runtime::sync::TickDamage| {
                    scans.heard_tick(t, &host)
                }));
            }
            if let Some(scans) = damage_scans {
                app.manage(scans);
            }
            app.manage(sync);
            app.manage(update_jobs);
            app.manage(state);
            app.manage(earshot_runtime::search::Searches::default());
            app.manage(retention);
            let handle = app.handle().clone();
            let sink: meeting::Sink = Arc::new(move |e: meeting_events::MeetingEvent| {
                // Only to this app's own webview; nothing leaves the device.
                let _ = e.emit(&handle);
                if let Some(shell) = handle.try_state::<Arc<shell::Shell>>() {
                    shell.on_meeting_event(&e);
                }
            });
            let driver = meeting::MeetingDriver::new(
                Arc::new(meeting::HostPrepare::wasapi().with_computers(Arc::clone(&computers))),
                sink,
                Arc::new(Instant::now),
                gate.clone(),
                &cuda_latch,
            );
            let meeting_queue = driver.queue();
            app.manage(driver);
            let handle = app.handle().clone();
            let job_sink: jobs::JobSink = Arc::new(move |e: jobs::JobEvent| {
                let _ = e.emit(&handle);
                if let Some(shell) = handle.try_state::<Arc<shell::Shell>>() {
                    shell.on_job_event(&e);
                }
            });
            let job_runner = jobs::JobRunner::new(
                Arc::new(jobs::HostJobs { computers }),
                job_sink,
                gate.clone(),
                &cuda_latch,
            );
            // Sync (T11.3a) starts off the setup path (Credential Manager is read first), once
            // summary offload's host exists (T11.3db).
            // What a tick brought reaches the window as ids only (T12.81); only to this app's
            // own webview, nothing leaves the device.
            let handle = app.handle().clone();
            sync_for_start.set_change_listener(Arc::new(
                move |c: &earshot_runtime::sync::SyncChanges| {
                    let _ = sync_settings::sync_event(c).emit(&handle);
                },
            ));
            if let Ok(services) = app.state::<ipc::AppState>().services() {
                sync_for_start.set_offload_host(Arc::new(offload::HostOffload::new(
                    services.clone(),
                    job_runner.clone(),
                    meeting_queue,
                    gate.clone(),
                    Arc::new(offload::HostHelperWork::installed()),
                )));
                let _ = std::thread::Builder::new()
                    .name("earshot-sync-start".into())
                    .spawn(move || {
                        // The one-off copy of 0.4.2 ignores (T12.93, now only without a vault),
                        // the one-off removal repair whether sync is on or off (T14.49e), then
                        // the sync thread.
                        let _ = sync_for_start.start_up(&services);
                    });
            }
            app.manage(job_runner);
            let model_sink: model_jobs::ModelSink = emitter(app.handle());
            let model_jobs = model_jobs::ModelJobs::new(
                Arc::new(model_jobs::HostModelWork),
                model_sink,
                gate.clone(),
            );
            app.manage(model_jobs.clone());
            let cuda_sink: cuda_settings::CudaSink = emitter(app.handle());
            // A run that chose CUDA for transcription finds the stored check out of date.
            if let Ok(services) = app.state::<ipc::AppState>().services() {
                cuda_settings::check_after_start(
                    cuda_latch,
                    services,
                    model_jobs.clone(),
                    Arc::clone(&cuda_sink),
                );
            }
            app.manage(cuda_settings::CudaJobs::new(
                cuda_files, cuda_sink, model_jobs,
            ));
            app.manage(gate.clone());
            let voice_sink: speaker_settings::VoiceSink = emitter(app.handle());
            app.manage(speaker_settings::VoiceJobs::new(
                Arc::new(speaker_settings::HostVoiceWork),
                voice_sink,
                gate.clone(),
            ));
            let check_sink: audio_check::AudioCheckSink = emitter(app.handle());
            app.manage(audio_check::AudioCheckJobs::new(
                Arc::new(audio_check::HostAudioCheckWork),
                check_sink,
                gate.clone(),
            ));
            let bench_sink: benchmark::BenchmarkSink = emitter(app.handle());
            app.manage(benchmark::BenchmarkJobs::new(
                Arc::new(benchmark::HostBenchmarkWork),
                bench_sink,
                gate.clone(),
            ));
            let min_size = app
                .config()
                .app
                .windows
                .iter()
                .find(|w| w.label == "main")
                .and_then(|w| Some((w.min_width?, w.min_height?)));
            app.manage(ipc::CompactWindow::new(min_size));
            app.manage(shell::ShortcutStatus::default());
            let shell = Arc::new(shell::Shell::new(app.handle().clone()));
            app.manage(Arc::clone(&shell));
            let tray = shell.build_tray();
            shell.register_shortcut();
            shell.spawn_call_start_watch();
            // The window starts hidden: started by Windows it stays so (T7.5), unless there is
            // no tray to open it from.
            let shows_window = !by_windows || tray.is_err();
            if shows_window {
                shell.show_window();
            }
            // In the tray with a store that failed to open: a notification says so (T14.9).
            shell.tell_start_problems(shows_window);
            Ok(())
        })
        .build(tauri::generate_context!())
        .expect("the Earshot window could not start")
        .run(|app, event| {
            // The last event before the process ends, also when Windows restarts, shuts down or
            // signs out (tao turns `WM_ENDSESSION` into it, then exits): a recording is saved
            // first (T9.19). If `WM_ENDSESSION` arrives while tao is already inside its event
            // handler, tao exits without this event; start-up recovery (T9.18) is the backstop.
            if let tauri::RunEvent::Exit = event {
                shell::save_before_exit(app);
            }
        });
}
